from collections import deque
class Solution:
    def collectTheCoins(self, coins: List[int], edges: List[List[int]]) -> int:
        n = len(coins)
        adj = [[] for _ in range(n)]
        deg = [0] * n
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
            deg[a] += 1; deg[b] += 1
        alive = [True] * n
        q = deque(i for i in range(n) if coins[i] == 0 and deg[i] == 1)
        while q:
            u = q.popleft()
            alive[u] = False
            for v in adj[u]:
                if alive[v]:
                    deg[v] -= 1
                    if deg[v] == 1 and coins[v] == 0:
                        q.append(v)
        for _ in range(2):
            leaves = [u for u in range(n) if alive[u] and deg[u] <= 1]
            for u in leaves:
                alive[u] = False
                for v in adj[u]:
                    if alive[v]:
                        deg[v] -= 1
        left = sum(alive)
        return max(0, 2 * (left - 1))

