class Solution {
public:
    int collectTheCoins(vector<int>& coins, vector<vector<int>>& edges) {
        int n = coins.size();
        vector<vector<int>> adj(n);
        vector<int> deg(n, 0);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]);
            deg[e[0]]++; deg[e[1]]++;
        }
        vector<char> alive(n, 1);
        queue<int> q;
        for (int i = 0; i < n; ++i)
            if (!coins[i] && deg[i] == 1) q.push(i);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            alive[u] = 0;
            for (int v : adj[u]) if (alive[v] && --deg[v] == 1 && !coins[v]) q.push(v);
        }
        for (int r = 0; r < 2; ++r) {
            vector<int> leaves;
            for (int u = 0; u < n; ++u) if (alive[u] && deg[u] <= 1) leaves.push_back(u);
            for (int u : leaves) {
                alive[u] = 0;
                for (int v : adj[u]) if (alive[v]) --deg[v];
            }
        }
        int left = 0;
        for (int u = 0; u < n; ++u) left += alive[u];
        return max(0, 2 * (left - 1));
    }
};

