class Solution {
    public int collectTheCoins(int[] coins, int[][] edges) {
        int n = coins.length;
        List<List<Integer>> adj = new ArrayList<>();
        int[] deg = new int[n];
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]);
            deg[e[0]]++; deg[e[1]]++;
        }
        boolean[] alive = new boolean[n];
        Arrays.fill(alive, true);
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; ++i) if (coins[i] == 0 && deg[i] == 1) q.add(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            alive[u] = false;
            for (int v : adj.get(u))
                if (alive[v] && --deg[v] == 1 && coins[v] == 0) q.add(v);
        }
        for (int r = 0; r < 2; ++r) {
            List<Integer> leaves = new ArrayList<>();
            for (int u = 0; u < n; ++u) if (alive[u] && deg[u] <= 1) leaves.add(u);
            for (int u : leaves) {
                alive[u] = false;
                for (int v : adj.get(u)) if (alive[v]) --deg[v];
            }
        }
        int left = 0;
        for (boolean b : alive) if (b) left++;
        return Math.max(0, 2 * (left - 1));
    }
}

