var collectTheCoins = function(coins, edges) {
    const n = coins.length;
    const adj = Array.from({length: n}, () => []);
    const deg = new Array(n).fill(0);
    for (const [a, b] of edges) {
        adj[a].push(b); adj[b].push(a);
        deg[a]++; deg[b]++;
    }
    const alive = new Array(n).fill(true);
    let q = [];
    for (let i = 0; i < n; ++i) if (coins[i] === 0 && deg[i] === 1) q.push(i);
    while (q.length) {
        const nq = [];
        for (const u of q) {
            alive[u] = false;
            for (const v of adj[u])
                if (alive[v] && --deg[v] === 1 && coins[v] === 0) nq.push(v);
        }
        q = nq;
    }
    for (let r = 0; r < 2; ++r) {
        const leaves = [];
        for (let u = 0; u < n; ++u) if (alive[u] && deg[u] <= 1) leaves.push(u);
        for (const u of leaves) {
            alive[u] = false;
            for (const v of adj[u]) if (alive[v]) --deg[v];
        }
    }
    const left = alive.filter(Boolean).length;
    return Math.max(0, 2 * (left - 1));
};
